#include "../src/passenger_render.h"
#include <stdio.h>
int main(void){FILE *f=fopen("outputs/crazy-taxi-native/assets/driving.ctr","rb");if(!f)return 1;unsigned char b[16388];if(fread(b,1,sizeof b,f)!=sizeof b)return 2;fclose(f);TaxiTrig t;taxi_trig_decode(&t,b+4,b+8196);int x,y,z,yaw,pitch,horizontal,vertical;unsigned scale;while(scanf("%d %d %d %u %d %d %d %d",&x,&y,&z,&scale,&yaw,&pitch,&horizontal,&vertical)==8){TaxiPassengerMarkerRequest q={.descriptor=0x087ec5d8u,.x=x,.y=y,.z=z,.scale=scale};TaxiPassengerRender p;int rc=taxi_passenger_marker_render_frustum(&q,(TaxiPoint){0,0,0},yaw,pitch,&t,horizontal,vertical,&p);printf("%d",rc);if(rc==1){printf(" %ld %ld %ld %ld %u",(long)p.screen.left,(long)p.screen.top,(long)p.screen.right,(long)p.screen.bottom,p.bucket);for(unsigned i=0;i<4;i++)printf(" %ld %ld",(long)p.u[i],(long)p.v[i]);}puts("");}return 0;}
